<!doctype html><html><head><meta charset="utf-8"><title><?= e($title) ?></title><style>body{font:14px Arial,sans-serif;max-width:760px;margin:24px auto;color:#111}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #ddd;padding:6px;text-align:left}.r{text-align:right}h1{margin:0}@media print{button{display:none}}</style></head><body>
<button onclick="print()">Print</button><h1><?= e(setting('company_legal_name') ?: setting('brand_name')) ?></h1><p style="margin:0;font-size:12px;color:#444"><?= e(setting('contact_address')) ?><?= setting('contact_phone') ? ' · ' . e(setting('contact_phone')) : '' ?><?= setting('contact_email') ? ' · ' . e(setting('contact_email')) : '' ?><br><?= setting('company_gst') ? 'GSTIN: ' . e(setting('company_gst')) . ' &nbsp; ' : '' ?><?= setting('company_license') ? 'Licence: ' . e(setting('company_license')) : '' ?></p><?php if (setting('invoice_header_note')): ?><p><i><?= e(setting('invoice_header_note')) ?></i></p><?php endif; ?><p>Order <b><?= e($o['reference']) ?></b> · <?= e(date('d M Y h:i A', strtotime($o['created_at']))) ?> · Status: <?= e(order_statuses()[$o['status']]) ?> · Payment: <?= e($o['payment_status']) ?> (<?= e($o['payment_method']) ?>) · Source: <?= e($o['order_source']) ?></p>
<p><b><?= e($o['customer_name']) ?></b> · <?= e($o['mobile']) ?><br><?= nl2br(e($o['address'])) ?>, <?= e($o['city']) ?>, <?= e($o['state']) ?> – <?= e($o['pincode']) ?></p>
<table><tr><th>SKU</th><th>Item</th><th class="r">Price</th><th class="r">Qty</th><th class="r">Total</th></tr><?php foreach ($o['items'] as $i): ?><tr><td><?= e($i['sku']) ?></td><td><?= e($i['name']) ?></td><td class="r"><?= money($i['unit_price']) ?></td><td class="r"><?= (int)$i['quantity'] ?></td><td class="r"><?= money($i['line_total']) ?></td></tr><?php endforeach; ?></table>
<p class="r">Subtotal <?= money($o['subtotal']) ?> · Discount −<?= money($o['discount_total']) ?> · Delivery <?= money($o['delivery_charge']) ?><br><b>Total <?= money($o['total']) ?></b></p><?php if (setting('company_upi_id') || setting('company_bank_account')): ?><p style="font-size:12px"><b>Pay to:</b> <?= setting('company_upi_id') ? 'UPI ' . e(setting('company_upi_id')) . ' · ' : '' ?><?= setting('company_bank_account') ? e(setting('company_bank_name')) . ' A/c ' . e(setting('company_bank_account')) . ' IFSC ' . e(setting('company_bank_ifsc')) . ' (' . e(setting('company_bank_holder')) . ')' : '' ?></p><?php endif; ?><?php if (setting('invoice_terms')): ?><p style="font-size:11px;color:#555"><b>Terms:</b> <?= nl2br(e(setting('invoice_terms'))) ?></p><?php endif; ?><p style="text-align:center;font-size:12px"><?= e(setting('invoice_footer') ?: 'Thank you for your order!') ?></p></body></html>
